// <p id="saludo">Hola</p>
const p = document.getElementById("saludo");
console.log(p.textContent); // Hola
document.getElementById("#saludo"); // null (sobra el #)

const li = document.createElement("li");
li.textContent = "Comprar pan";
li.className = "item";
li.dataset.id = "7";
document.querySelector("ul").append(li); // recién ahora se ve

const ul = document.querySelector("ul");
const a = document.createElement("li");
const b = document.createElement("li");
ul.append(a, b, "texto suelto");             // varios a la vez
ul.appendChild(document.createElement("li")); // solo un nodo
ul.prepend(document.createElement("li"));     // al inicio

const item = document.querySelector("#item-3");
item.remove(); // desaparece de la página

const lista = document.querySelector("ul");
lista.replaceChildren(); // la lista queda vacía

const p = document.querySelector("p");
