const menu = document.querySelector(".menu");
menu.classList.add("abierto");
menu.classList.remove("oculto");
menu.classList.toggle("activo");       // la pone si no está, la quita si está
menu.classList.toggle("oscuro", true); // fuerza ponerla
console.log(menu.classList.contains("abierto")); // true

// <button data-producto-id="42">Comprar</button>
