form.addEventListener("submit", (e) => {
  e.preventDefault(); // la página NO se recarga
  const datos = new FormData(form);
  console.log(datos.get("email")); // lo que escribió el usuario
});

// Modal: clic en el fondo lo cierra, clic dentro de la caja no
fondo.addEventListener("click", cerrarModal);
caja.addEventListener("click", (e) => {
  e.stopPropagation(); // el clic ya no llega al fondo
});
// alternativa sin stopPropagation: if (e.target === fondo) cerrarModal();

// <ul id="lista"><li>Pan <button class="borrar">x</button></li>...</ul>
lista.addEventListener("click", (e) => {
  const btn = e.target.closest("button.borrar");
  if (!btn) return; // el clic no fue en un botón borrar
  btn.closest("li").remove();
});

